package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.StringUtils.containsIgnoreCase
 */
public class StringUtils_containsIgnoreCase_TriageGen2Test {

    @Test
    public void testContainsIgnoreCase_NullStr() {
        assertFalse("Should return false if str is null", 
            StringUtils.containsIgnoreCase(null, "abc"));
    }

    @Test
    public void testContainsIgnoreCase_NullSearchStr() {
        assertFalse("Should return false if searchStr is null", 
            StringUtils.containsIgnoreCase("abc", null));
    }

    @Test
    public void testContainsIgnoreCase_BothNull() {
        assertFalse("Should return false if both are null", 
            StringUtils.containsIgnoreCase(null, null));
    }

    @Test
    public void testContainsIgnoreCase_ExactMatch() {
        assertTrue("Should return true for exact match", 
            StringUtils.containsIgnoreCase("hello", "hello"));
    }

    @Test
    public void testContainsIgnoreCase_CaseInsensitiveMatch() {
        assertTrue("Should return true for case-insensitive match", 
            StringUtils.containsIgnoreCase("HelloWorld", "world"));
        assertTrue("Should return true for case-insensitive match (uppercase)", 
            StringUtils.containsIgnoreCase("helloworld", "WORLD"));
    }

    @Test
    public void testContainsIgnoreCase_SubstringMatch() {
        assertTrue("Should return true when searchStr is a substring", 
            StringUtils.containsIgnoreCase("java programming", "prog"));
    }

    @Test
    public void testContainsIgnoreCase_NoMatch() {
        assertFalse("Should return false when no match is found", 
            StringUtils.containsIgnoreCase("abcdef", "gh"));
    }

    @Test
    public void testContainsIgnoreCase_EmptySearchStr() {
        // Based on standard StringUtils behavior, an empty search string is usually contained in any non-null string
        // The provided implementation uses str.toUpperCase().contains("".toUpperCase())
        assertTrue("Should return true for empty searchStr in non-null str", 
            StringUtils.containsIgnoreCase("abc", ""));
    }

    @Test
    public void testContainsIgnoreCase_EmptyStr() {
        assertFalse("Should return false if str is empty and searchStr is not", 
            StringUtils.containsIgnoreCase("", "a"));
    }

    @Test
    public void testContainsIgnoreCase_BothEmpty() {
        assertTrue("Should return true if both are empty strings", 
            StringUtils.containsIgnoreCase("", ""));
    }

    @Test
    public void testContainsIgnoreCase_SpecialCharacters() {
        assertTrue("Should handle special characters case-insensitively", 
            StringUtils.containsIgnoreCase("!@#$%", "!@#"));
    }
}
